public(package) fun liquidate_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    ctokens: Coin<CToken<MarketType, CoinType>>,
    liq_revenue_factor: Decimal,
): Balance<CoinType> {
    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());

    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());

    let protocol_seize_amount = liq_revenue_factor.int_mul(redeem_collateral_amount);
    let liquidator_seize_amount = redeem_collateral_amount - protocol_seize_amount;

    self.cash_reserve = self.cash_reserve.add(math::float::from(protocol_seize_amount));

    self.decrease_ctoken_supply(ctokens.into_balance());
    self.withdraw_underlying(liquidator_seize_amount)
}

public(package) fun burn_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    ctokens: Coin<CToken<MarketType, CoinType>>,
): Balance<CoinType> {
    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());

    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());

    self.decrease_ctoken_supply(ctokens.into_balance());
    self.withdraw_underlying(redeem_collateral_amount)
}

public(package) fun borrow_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
    assert!(self.cash - self.cash_reserve.ceil() > amount, error::reserve_not_enough_error());

    self.debt = self.debt.add_u64(amount);
    self.withdraw_underlying(amount)
}

public(package) fun repay_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, coin: Coin<CoinType>) {
    let repay_amount = float::from(coin.value());

    if (self.debt.lt(repay_amount)) {
        let total_debt = self.debt.ceil();

        // repay amount is more than debt, considered as donation to reserve
        self.cash_reserve = self.cash_reserve.add_u64( coin.value() - total_debt);
        self.debt = math::float::zero();
    } else {
        self.debt = self.debt.sub(repay_amount);
    };

fun liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
    exchange_rate: Decimal,
    liquidation_incentive: Decimal,
    actual_repay_amount: u64,

    oracle_base_token: x_oracle::x_oracle::BaseToken,
    x_oracle: &XOracle,

    coin_registry: &CoinDecimalsRegistry,
    clock: &Clock,
): u64 {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let price_borrowed = get_spot_price(x_oracle, debt_type, oracle_base_token, clock);
    let price_collateral = get_spot_price(x_oracle, collateral_type, oracle_base_token, clock);

    let actual_repay_amount = float::from(actual_repay_amount);

    let debt_decimals = math::u64::pow10_u64(coin_registry.decimals(debt_type));
    let collateral_decimals = math::u64::pow10_u64(coin_registry.decimals(collateral_type));

    /*
     * Get the exchange rate and calculate the number of collateral tokens to seize:
     *  seizeAmount = (actualRepayAmount + actualRepayAmount * liquidationIncentive) * priceBorrowed / priceCollateral
     *  seizeTokens = seizeAmount / exchangeRate
     */
    let incentivised_borrow = actual_repay_amount.add(actual_repay_amount.mul(
        liquidation_incentive,
    ));
    // ignoreing decimal calculation as they will be cancelled out
    let incentivised_borrow_usd = incentivised_borrow.mul(price_borrowed).div_u64(debt_decimals);
    let seize_collaterals = incentivised_borrow_usd.div(price_collateral).mul_u64(collateral_decimals);

    let seize_ctokens = seize_collaterals.div(exchange_rate);

    assert!(
        seize_ctokens.lt(float::from(std::u64::max_value!())),
        error::invariant_seize_tokens_crazy_big(),
    );

    // only take the tecnnically possible amount
    seize_ctokens.floor()
}

